namespace rvv_kernel {

#include <stddef.h>
#include <assert.h>

void test_rvv(
    size_t batch,
    const float* input_a,
    const float* input_b,
    float* output,
    const struct xnn_f32_default_params* params)
{
  assert(batch != 0);
  assert(batch % sizeof(float) == 0);
  assert(input_a != NULL);
  assert(input_b != NULL);
  assert(output != NULL);

  size_t n = batch / sizeof(float);

  // Saturn is a short-vector microarchitecture. Using a large LMUL (m8) is critical
  // to increase the instruction chime length. This hides functional unit latencies 
  // (e.g., the 2-stage FP compare/min/max pipeline) and reduces pressure on the 
  // scalar instruction fetch unit.
  const size_t vlmax = __riscv_vsetvlmax_e32m8();

  // Strategy 21: Replace the complex pointer-difference logic in the loop condition 
  // with a dedicated scalar down-counter to streamline scalar ALU operations and 
  // reduce register pressure.
  while (n >= vlmax) {
    // Saturn's Decoupled Access-Execute (DAE) design allows the Load sequencer (VLS)
    // to run ahead of the Datapath (VXS) and Store (VSS) sequencers.
    // The instructions below are structured to facilitate chaining across these sequencers.
    vfloat32m8_t va = __riscv_vle32_v_f32m8(input_a, vlmax);
    vfloat32m8_t vb = __riscv_vle32_v_f32m8(input_b, vlmax);

    // vfmax targets the VXS sequencer (FPConvPipe).
    vfloat32m8_t vacc = __riscv_vfmax_vv_f32m8(va, vb, vlmax);

    // vse targets the VSS sequencer.
    __riscv_vse32_v_f32m8(output, vacc, vlmax);

    // Increment pointers by the fixed vlmax. Scalar arithmetic overlaps with 
    // vector execution due to decoupling.
    input_a += vlmax;
    input_b += vlmax;
    output += vlmax;
    n -= vlmax;
  }

  // Variable-Length Tail Block: Process the remaining elements.
  // We only execute a vsetvl instruction here for the fractional remainder.
  if (n > 0) {
    size_t vl = __riscv_vsetvl_e32m8(n);
    
    vfloat32m8_t va = __riscv_vle32_v_f32m8(input_a, vl);
    vfloat32m8_t vb = __riscv_vle32_v_f32m8(input_b, vl);

    vfloat32m8_t vacc = __riscv_vfmax_vv_f32m8(va, vb, vl);

    __riscv_vse32_v_f32m8(output, vacc, vl);
  }
}

} // namespace rvv_kernel


// returns 0=VERIFIED, 1=COUNTEREXAMPLE, 2=TIMEOUT/UNKNOWN
int verify(size_t batch, size_t vlen, double timeout_s) {
    VerificationContext ctx(vlen);
    g_ctx = &ctx;
    const size_t cap = batch + 16;   // over-allocate; exact size not needed
    std::vector<float> input_a_arr(cap, (float)0);
    auto& _b_input_a = ctx.registerBuffer("input_a", cap * sizeof(float)); _b_input_a.bind(input_a_arr.data());
    std::vector<float> input_b_arr(cap, (float)0);
    auto& _b_input_b = ctx.registerBuffer("input_b", cap * sizeof(float)); _b_input_b.bind(input_b_arr.data());
    std::vector<float> output_neon_arr(cap, (float)0), output_rvv_arr(cap, (float)0);
    auto& _b_output_neon = ctx.registerBuffer("output_neon", cap * sizeof(float)); _b_output_neon.bind(output_neon_arr.data());
    auto& _b_output_rvv  = ctx.registerBuffer("output_rvv",  cap * sizeof(float)); _b_output_rvv.bind(output_rvv_arr.data());
    xnn_f32_default_params params{};
    const size_t _kbound = batch * 4;  // elements -> bytes

    neon_kernel::test_neon(_kbound, input_a_arr.data(), input_b_arr.data(), output_neon_arr.data(), &params);
    rvv_kernel ::test_rvv(_kbound, input_a_arr.data(), input_b_arr.data(), output_rvv_arr.data(), &params);

    Term eq =         buffers_equal(ctx.tm, _b_output_neon, _b_output_rvv, batch, sizeof(float), ElementKind::F32, 0);
    ctx.assert_(ctx.lnot_(eq));
    if (timeout_s > 0) ctx.set_query_timeout_ms((uint64_t)(timeout_s * 1000.0));
    printf("{\"status\":\"SOLVING\",\"batch\":%zu,\"vlen\":%zu,\"config\":\"%s\"}\n", batch, vlen, "no-params");
    CheckResult _r = ctx.check();
    if (_r == CheckResult::Unsat) {
        printf("{\"status\":\"VERIFIED\",\"batch\":%zu,\"vlen\":%zu,\"config\":\"%s\"}\n", batch, vlen, "no-params");
        return 0;
    }
    if (_r == CheckResult::Unknown) {   // solver gave up (e.g. per-query timeout) — NOT a counterexample
        printf("{\"status\":\"TIMEOUT\",\"batch\":%zu,\"vlen\":%zu,\"config\":\"%s\"}\n", batch, vlen, "no-params");
        return 2;
    }
    size_t fi = 0;
    for (size_t e = 0; e < batch; e++) {
        Term n = ctx.solver->getValue(_b_output_neon.loadScalar(e * sizeof(float), 32));
        Term v = ctx.solver->getValue(_b_output_rvv.loadScalar(e * sizeof(float), 32));
        if (n.getBitVectorValue(10) != v.getBitVectorValue(10)) { fi = e; break; }
    }
    printf("{\"status\":\"COUNTEREXAMPLE\",\"batch\":%zu,\"vlen\":%zu,\"config\":\"%s\",\"fail_index\":%zu}\n", batch, vlen, "no-params", fi);
    return 1;
}

int main(int argc, char** argv) {
    setvbuf(stdout, NULL, _IOLBF, 0);   // line-buffer so per-batch status streams over a pipe
    if (argc < 3) { fprintf(stderr, "Usage: %s <start> <end(0=unbounded)> [vlen] [time_budget_s]\n", argv[0]); return 2; }
    size_t start = (size_t)atoi(argv[1]);
    size_t end   = (size_t)atoi(argv[2]);                 // 0 = unbounded: sweep until the time budget
    size_t vlen  = (argc > 3) ? (size_t)atoi(argv[3]) : 256;
    double budget = (argc > 4) ? atof(argv[4]) : 0.0;     // TOTAL wall-clock budget (s); 0 = none
    if (end == 0 && budget <= 0.0) budget = 600.0;        // unbounded needs a budget — default 10 min
    auto _t0 = std::chrono::steady_clock::now();
    auto _rem = [&]() -> double {                         // seconds left in the total budget (0 = no limit)
        if (budget <= 0.0) return 0.0;
        double e = std::chrono::duration<double>(std::chrono::steady_clock::now() - _t0).count();
        return budget - e;
    };
    size_t _last = start ? start - 1 : 0;
    for (size_t b = start; (end == 0 || b <= end); b++) {
        if (budget > 0.0 && _rem() <= 0.0) { printf("{\"status\":\"TIMEOUT\",\"batch\":%zu,\"vlen\":%zu}\n", b, vlen); break; }
        int r = verify(b, vlen, _rem());        // per-query limit = remaining total budget
        if (r == 1) return 1;   // counterexample — stop
        if (r == 2) break;      // batch hit the budget — larger batches only get harder
        _last = b;
    }
    printf("{\"status\":\"ALL_VERIFIED\",\"start\":%zu,\"end\":%zu,\"configs\":1}\n", start, _last);
    return 0;
}
